// Generated by scripts/sync-core.mjs from mobile/src/chain/keys.ts; edit it there and run npm run sync-core.
// Signature schemes of the standard policies (wiki: programs/policies):
// ECDSA on secp256k1 or P-256, uncompressed SEC1 public keys, low-S compact
// signatures over the signing digest. Deterministic (RFC 6979) nonces, so
// signing needs no randomness; key generation takes it from the caller.
import { p256 } from '@noble/curves/nist.js';
import { secp256k1 } from '@noble/curves/secp256k1.js';
import { hex, unhex } from './bytes';

export type Scheme = 'secp256k1' | 'p256';
export const SCHEMES: Scheme[] = ['secp256k1', 'p256'];

export const SCHEME_LABEL: Record<Scheme, string> = {
  secp256k1: 'secp256k1',
  p256: 'P-256',
};

export const SCHEME_HINT: Record<Scheme, string> = {
  secp256k1: 'The common curve; cheapest to verify.',
  p256: 'The curve of secure elements and passkeys; about six times the verification cost.',
};

function curve(scheme: Scheme) {
  return scheme === 'p256' ? p256 : secp256k1;
}

export function isValidSecret(scheme: Scheme, secret: Uint8Array): boolean {
  return curve(scheme).utils.isValidSecretKey(secret);
}

/** A fresh secret from `random` bytes, retried in the astronomically rare invalid case. */
export function randomSecret(scheme: Scheme, random: (n: number) => Uint8Array): Uint8Array {
  for (;;) {
    const secret = random(32);
    if (isValidSecret(scheme, secret)) return secret;
  }
}

/** Uncompressed SEC1 public key: the policy parameters of a key account. */
export function publicKey(scheme: Scheme, secret: Uint8Array): Uint8Array {
  return curve(scheme).getPublicKey(secret, false);
}

/** Low-S compact `r ‖ s` over a 32-byte digest. */
export function signDigest(scheme: Scheme, secret: Uint8Array, digest: Uint8Array): Uint8Array {
  return curve(scheme).sign(digest, secret, { prehash: false, lowS: true, format: 'compact' });
}

export function verifyDigest(
  scheme: Scheme,
  pub: Uint8Array,
  digest: Uint8Array,
  signature: Uint8Array,
): boolean {
  try {
    return curve(scheme).verify(signature, digest, pub, { prehash: false, lowS: true, format: 'compact' });
  } catch {
    return false;
  }
}

// ---- Device codes -------------------------------------------------------------
//
// What one device shows so that another can add it to an identity: the
// scheme and the public key. Pasted into "Add a device" on the other side.

export function deviceCode(scheme: Scheme, pub: Uint8Array): string {
  return `${scheme}:${hex(pub)}`;
}

export function parseDeviceCode(text: string): { scheme: Scheme; pub: Uint8Array } | null {
  const m = /^\s*(secp256k1|p256)\s*:\s*([0-9a-fA-F]{130})\s*$/.exec(text);
  if (!m) return null;
  const scheme = m[1] as Scheme;
  const pub = unhex(m[2].toLowerCase());
  try {
    curve(scheme).Point.fromHex(m[2].toLowerCase());
  } catch {
    return null;
  }
  return { scheme, pub };
}
